<?php if (!defined('ABSPATH')) { exit; } get_header(); $saved = isset($_GET['saved']) && is_home(); $home = is_home() && !$saved && !is_search(); ?>
<div class="site-layout"><?php get_template_part('template-parts/rail'); ?>
<main id="main-content" class="discovery-main">
<?php if ($home && !is_paged()): ?>
<section class="hero"><div class="hero-copy"><?php if (dh_opt('announcement')): ?><div class="hero-eyebrow"><span></span><?php echo esc_html(dh_opt('announcement')); ?></div><?php endif; ?><h1><?php echo esc_html(dh_opt('hero_title')); ?></h1><p><?php echo esc_html(dh_opt('hero_text')); ?></p><div class="hero-bottom"><span class="tiny-code">&lt;/&gt;</span><span>好用 · 免费 · 开放</span><span class="hero-line"></span><small>CURATED WITH CURIOSITY</small></div></div><div class="hero-art" aria-hidden="true"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="hero-code">&lt;/&gt;</span><i class="art-star">✦</i><b class="art-dot"></b></div></section>
<?php dh_ad('top'); $ids = array_slice(array_filter(array_map('absint', explode(',', dh_opt('featured_ids')))), 0, 3); if ($ids): $featured = new WP_Query(['post_type' => 'post', 'post_status' => 'publish', 'post__in' => $ids, 'category__not_in' => dh_app_excluded_categories(), 'orderby' => 'post__in', 'posts_per_page' => 3, 'ignore_sticky_posts' => true, 'no_found_rows' => true]); if ($featured->have_posts()): ?>
<section class="featured-section"><div class="section-heading"><h2><?php echo dh_icon('spark'); ?>编辑的心头好</h2><span class="section-caption">少一点选择，多一点惊喜</span></div><div class="featured-grid"><?php while ($featured->have_posts()): $featured->the_post(); ?><a class="featured-card" href="<?php the_permalink(); ?>"><div class="featured-top"><?php dh_product_icon(); ?><span><?php echo esc_html(dh_meta('badge') ?: '编辑精选'); ?> ↗</span></div><h3><?php echo esc_html(dh_title()); ?></h3><p><?php echo esc_html(wp_html_excerpt(dh_summary(), 42, '…')); ?></p></a><?php endwhile; wp_reset_postdata(); ?></div></section>
<?php endif; endif; ?>
<?php else: ?><section class="archive-intro"><span class="eyebrow"><?php echo $saved ? 'YOUR PERSONAL COLLECTION' : 'EXPLORE SOMETHING GOOD'; ?></span><h1><?php if ($saved) { echo '我的收藏'; } elseif (is_search()) { echo '搜索：' . esc_html(get_search_query()); } elseif (is_category() || is_tag()) { echo esc_html(single_term_title('', false)); } elseif (is_archive()) { echo esc_html(wp_strip_all_tags(get_the_archive_title())); } else { echo esc_html(dh_opt('hero_title')); } ?></h1><p><?php echo $saved ? '收藏保存在当前浏览器，换设备或清理浏览器后不会同步。最多展示最近 100 项。' : esc_html(wp_strip_all_tags(get_the_archive_description()) ?: '在这里，找到值得留下来的好软件。'); ?></p></section><?php endif; ?>
<section class="feed-section"><div class="feed-title"><h2><?php echo $saved ? dh_icon('bookmark') . '我的软件清单' : ($home ? '最新发现' : '发现列表'); ?><span class="feed-dot"></span></h2><div class="feed-sort"><?php if (!$saved): ?><a class="<?php echo !isset($_GET['sort']) ? 'selected' : ''; ?>" href="<?php echo esc_url(remove_query_arg('sort')); ?>">最新发布</a><?php if (dh_opt('votes')): ?><a class="<?php echo isset($_GET['sort']) ? 'selected' : ''; ?>" href="<?php echo esc_url(add_query_arg('sort', 'popular', get_pagenum_link(1))); ?>">人气推荐</a><?php endif; ?><?php endif; ?></div></div>
<?php if (!$saved): ?><nav class="category-chips" aria-label="软件分类"><a class="<?php echo is_home() ? 'selected' : ''; ?>" href="<?php echo esc_url(home_url('/')); ?>">全部</a><?php foreach (array_slice(dh_nav_categories(), 0, 7) as $term): ?><a class="<?php echo is_category($term->term_id) ? 'selected' : ''; ?>" href="<?php echo esc_url(get_category_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach; ?></nav><?php endif; ?>
<?php if (have_posts()): ?><div class="product-list"><?php $n = 0; while (have_posts()): the_post(); get_template_part('template-parts/card'); if (++$n === (int) dh_opt('ad_interval')) { dh_ad('feed'); } endwhile; ?></div>
<nav class="pagination" aria-label="文章分页"><?php echo paginate_links(['prev_text' => '← 上一页', 'next_text' => '下一页 →']); ?></nav>
<?php else: ?><div class="empty-state"><?php echo dh_icon($saved ? 'bookmark' : 'search'); ?><h2><?php echo $saved ? '把喜欢的软件，留在这里。' : '暂时没有找到相关内容'; ?></h2><p><?php echo $saved ? '点击软件旁的收藏图标，建立自己的工具清单。' : '试试其他关键词，或者浏览更多分类。'; ?></p><a class="button" href="<?php echo esc_url(home_url('/')); ?>">去发现好软件 <?php echo dh_icon('arrow'); ?></a></div><?php endif; ?></section>
</main><?php get_template_part('template-parts/sidebar'); ?></div><?php get_footer(); ?>
